"""从目录和实际方案生成静态预览页，不依赖在线服务。"""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
catalog=json.loads((ROOT/'目录.json').read_text())['components']
variants={}
for row in catalog:
 variants[row['id']]={v:json.loads((ROOT/'variants'/(row['id']+'-'+v+'.json')).read_text()) for v in ['short','default','long']}
examples=[{'id':p.stem,'spec':json.loads(p.read_text())} for p in sorted((ROOT/'sample-configs').glob('*.json'))]
data=json.dumps({'catalog':catalog,'variants':variants,'examples':examples},ensure_ascii=False).replace('</','<\\/')
HTML='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>nana mg1 · 独立动效组件</title><style>
*{box-sizing:border-box}body{margin:0;background:#0b1320;color:#edf3fc;font:16px/1.6 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:32px 24px 60px}h1{font-size:34px;margin:8px 0}h2{font-size:23px;margin:0 0 16px}p{color:#b8c7db}a{color:#a5e4ec}header{margin-bottom:26px}.grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(300px,1fr);gap:22px}.panel{padding:22px;border:1px solid #40546e;border-radius:14px;background:#132034}video{display:block;width:100%;aspect-ratio:16/9;background:#030811;border-radius:8px}label{display:block;margin:14px 0 6px;color:#d1deef}select,input,textarea,button{font:inherit;color:#edf3fc;background:#1b2c44;border:1px solid #637993;border-radius:7px;padding:10px 12px}select,textarea{width:100%}textarea{height:270px;font:13px/1.6 monospace;resize:vertical}input[type=text]{width:100%}button{min-height:44px;cursor:pointer}button:hover{background:#2d4762}.row{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.row button.active{background:#24607a;border-color:#98dce7}small{color:#b1c4da}.status{min-height:48px;color:#b9e5ce}code{overflow-wrap:anywhere;color:#c8e6f8}.example-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.example-grid button{display:block;width:100%;text-align:left;padding:12px}.example-grid img{width:100%;aspect-ratio:16/9;object-fit:contain;background:#090e19;border-radius:6px}.example-grid strong{display:block;font-size:15px;margin-top:8px}section{margin-top:26px}.note{padding:14px 18px;background:#15293a;border-left:3px solid #88d6e5;border-radius:4px}.meta{font-size:14px;color:#b6c7df}.steps{margin-top:12px;padding:12px;background:#0c1728;border-radius:8px}@media(max-width:850px){.grid{grid-template-columns:1fr}.example-grid{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:24px 16px}h1{font-size:29px}}
</style></head><body><main><header><small>NANA MG1 · 15个独立组件</small><h1>选一个动作，换成自己的内容</h1><p>先看已渲染的短、中、长样例，再导出配置。每个组件可独立预览和渲染。</p><a href="README.md">使用说明</a> · <a href="验证结果.json">查看验证记录</a> · <a href="../README.md">返回风格库</a></header><div class="grid"><div class="panel"><h2 id="preview-name">组件预览</h2><video id="player" controls muted playsinline preload="metadata"></video><div class="row" id="variants"><button data-variant="short">短版 · 3秒</button><button data-variant="default">默认版</button><button data-variant="long">长版 · 8秒</button></div><p class="meta" id="preview-meta"></p><p class="note">播放器展示已渲染样例。编辑右侧配置后，需要重新构建和渲染，视频才会更新。</p><div class="steps"><small>从仓库根目录构建：</small><br><code id="command"></code></div></div><div class="panel"><h2>替换内容</h2><label for="component">选择组件</label><select id="component"></select><label for="title">标题</label><input type="text" id="title"><label for="duration">时长（按所选组件范围）</label><input type="number" id="duration" min="3" max="12" step="0.1"><label for="config">完整配置</label><textarea id="config" spellcheck="false"></textarea><div class="row"><button id="apply">应用到配置</button><button id="export">导出配置</button></div><p class="status" id="status">选择组件后查看配置。</p></div></div><section class="panel"><h2>5个参数替换测试片段</h2><p>这些片段只检验替换参数。原素材复现与左右对比另见本地交付。</p><div class="example-grid" id="examples"></div></section><section class="panel"><h2>这次验证覆盖什么</h2><p>每个组件都有3秒、默认时长和8秒方案，分别替换短文案、长文案与横图、竖图、方图。输入超出支持范围会报错，不会偷偷裁字。实际完成数量和检查结果以验证记录为准。</p><small>当前支持1920×1080、30fps、16:9。源动作的对象和分组被保留；不同内容和时长不等于逐帧复刻。原片左右对比另存于本地验收目录。</small></section></main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.querySelector('#data').textContent),select=document.querySelector('#component'),box=document.querySelector('#config'),title=document.querySelector('#title'),duration=document.querySelector('#duration'),status=document.querySelector('#status'),player=document.querySelector('#player');let active='07-takeaway';
for(const row of D.catalog){const option=document.createElement('option');option.value=row.id;option.textContent=row.id+' · '+row.name;select.append(option);}select.value=active;
function showSpec(spec,label,video,poster){active=spec.component;select.value=active;box.value=JSON.stringify(spec,null,2);title.disabled=!Object.hasOwn(spec.content,'title');title.value=spec.content.title||'';title.placeholder=title.disabled?'此组件只替换图片，不显示标题':'';duration.value=spec.duration;duration.min=(spec.component==='07-takeaway'&&spec.options.exit_mode!=='dissolve')?3:D.catalog.find(x=>x.id===spec.component).duration_range[0];document.querySelector('#preview-name').textContent=label;player.src=video;player.poster=poster;document.querySelector('#preview-meta').textContent=spec.duration+'秒 · 1920×1080 · 30fps · 图片保持原比例';document.querySelector('#command').textContent='python3 nana-mg-1/components/构建.py --config 配置.json --output .build/my-clip';status.textContent='配置已载入。修改后导出，再重新构建。';}
function choose(variant){const row=D.catalog.find(x=>x.id===active);showSpec(D.variants[active][variant],row.name+' · '+({short:'短版',default:'默认版',long:'长版'}[variant]),'previews/validation/'+active+'-'+variant+'.mp4','previews/covers/'+active+'.png');for(const b of document.querySelectorAll('[data-variant]'))b.classList.toggle('active',b.dataset.variant===variant);}
select.onchange=()=>{active=select.value;choose('default')};for(const b of document.querySelectorAll('[data-variant]'))b.onclick=()=>choose(b.dataset.variant);
document.querySelector('#apply').onclick=()=>{try{const s=JSON.parse(box.value);if(!title.disabled)s.content.title=title.value;const t=Number(duration.value);if(!Number.isFinite(t)||t<Number(duration.min)||t>12||Math.abs(t*30-Math.round(t*30))>0.00001)throw Error('时长须在'+duration.min+'至12秒，并按1/30秒对齐。');s.duration=t;box.value=JSON.stringify(s,null,2);status.textContent='配置已更新。导出后重新构建，播放器仍展示已有样例。';}catch(e){status.textContent=e instanceof SyntaxError?'JSON格式有误，请检查引号、逗号和括号。':e.message;}};
document.querySelector('#export').onclick=()=>{try{const s=JSON.parse(box.value);const url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='配置.json';a.click();URL.revokeObjectURL(url);status.textContent='已导出配置。使用说明中有构建与渲染命令。';}catch(e){status.textContent='JSON格式有误，修正后再导出。';}};
for(const ex of D.examples){const b=document.createElement('button'),im=document.createElement('img'),name=document.createElement('strong');im.src='previews/covers/'+ex.spec.component+'.png';name.textContent=ex.id.substring(3)+' · '+ex.spec.duration+'秒';b.append(im,name);b.onclick=()=>{showSpec(ex.spec,ex.id.substring(3),'previews/clips/'+ex.id+'.mp4',im.src);for(const item of document.querySelectorAll('[data-variant]'))item.classList.remove('active');player.scrollIntoView({block:'center'});};document.querySelector('#examples').append(b);}choose('default');
</script></body></html>'''
(ROOT/'预览.html').write_text(HTML.replace('__DATA__',data))
print('预览页已生成')
